-- Based on the schema shipped in spring-modulith-events-jdbc 1.4.0.
-- Only bounded notification metadata is registered; policy/device documents are not serialized here.
CREATE TABLE EVENT_PUBLICATION (
    ID VARCHAR(36) NOT NULL,
    LISTENER_ID VARCHAR(512) NOT NULL,
    EVENT_TYPE VARCHAR(512) NOT NULL,
    SERIALIZED_EVENT VARCHAR(4000) NOT NULL,
    PUBLICATION_DATE TIMESTAMP(6) NOT NULL,
    COMPLETION_DATE TIMESTAMP(6) DEFAULT NULL,
    PRIMARY KEY(ID)
);
CREATE INDEX EVENT_PUBLICATION_BY_COMPLETION_DATE_IDX ON EVENT_PUBLICATION(COMPLETION_DATE);
